/** A Zig error from a binding: the error's name in `code`. */
export class PlumeError<Code extends string = string> extends Error {
  readonly code: Code;
  constructor(code: Code, message?: string) {
    super(message ?? code);
    this.name = "PlumeError";
    this.code = code;
  }
}

export interface Person {
  name: string;
  age: number;
  mood: Mood;
  tags: string[];
}

export type Mood = "happy" | "curious" | "tired";

export interface Greeting {
  text: string;
  letters: number;
  shout: boolean;
}

export type Shape =
  | { tag: "circle"; value: number }
  | { tag: "rectangle"; value: { width: number; height: number; } }
  | { tag: "point" };

export interface Ping {
  text: string;
  times: number;
}

export interface Pong {
  text: string;
}

export interface Burst {
  thread: number;
  index: number;
}

